custom_css:
/*
 * ============================================================
 *  Mikufans —— SillyTavern 主题
 *  视觉参考：mikufans.cn（2009，DedeCMS v5.3 grass green）
 *  取色与构件全部来自本地站点存档：
 *    · 色板   → templets/style/dedecms.css、page.css（草绿 + 蓝链接 + 橙强调）
 *    · 构件   → templets/style/layout.css 的 dl.tbox 方框、虚线列表、日期徽标
 *    · 字体   → 12px Verdana/Arial/Tahoma + 宋体
 *  本文件只放变量，不放具体样式；改观感优先改这里。
 * ============================================================
 */

:root {
    /* ---------- 纸与绿（页面底 / 块底） ---------- */
    --mf-paper: #FFFFFF;             /* 内容块、正文底 */
    --mf-paper-2: #FCFDFA;           /* 次级块、表格斑马 */
    --mf-green-bg: #F4F8EE;          /* 门户块底（原站 .place / 搜索条） */
    --mf-green-bg-2: #F8FAEB;        /* 列表悬停、浅绿高亮 */
    --mf-titlebar-t: #F7FBF3;        /* 标题条渐变起 */
    --mf-titlebar-b: #EAF2E2;        /* 标题条渐变止 */

    /* ---------- 线 ---------- */
    --mf-line: #C5DDBC;              /* 主边框（tbox 外框） */
    --mf-line-2: #EAF2DE;            /* 浅边框（面包屑上下线） */
    --mf-line-3: #E5EFD6;            /* 更浅的分隔 */
    --mf-dash: #DCEBD7;              /* 虚线列表分隔 */
    --mf-frame: #E3E3E3;             /* 图片框 */
    --mf-frame-2: #DDDDDD;           /* 头像框 */
    --mf-inset-t: #666666;           /* 内凹框：上/左暗边 */
    --mf-inset-b: #BBBBBB;           /* 内凹框：下/右亮边 */

    /* ---------- 绿（标题与品牌） ---------- */
    --mf-title: #4A7749;             /* dl.tbox dt strong 标题绿 */
    --mf-title-2: #709C5A;           /* 面包屑 / 副标题绿 */
    --mf-green: #006900;             /* 链接式绿、选中 */
    --mf-green-deep: #003300;        /* 深绿 */
    --mf-brand-green: #4CAF50;       /* 字标 Mi */
    --mf-brand-cyan: #00B0D8;        /* 字标 ku */
    --mf-brand-pink: #FF0080;        /* 字标 Fans / 列表强调 */

    /* ---------- 字 ---------- */
    --mf-ink: #333333;
    --mf-ink-2: #666666;
    --mf-ink-3: #888888;
    --mf-ink-4: #999999;
    --mf-ink-5: #AAAAAA;

    /* ---------- 链接与强调 ---------- */
    --mf-link: #3366CC;              /* 原站 a */
    --mf-link-hover: #FF3333;        /* 原站 a:hover */
    --mf-accent: #FF6600;            /* 橙：当前页、计数 */
    --mf-accent-2: #FF6633;
    --mf-red: #C00000;               /* 按钮红 */
    --mf-red-hover: #E00000;
    --mf-announce: #FF0000;          /* 公告红字 */
    --mf-nav-hover: #8A0808;         /* 导航悬停深红 */

    /* ---------- 排版 ---------- */
    --mf-font: Verdana, Tahoma, "MS Sans Serif", SimSun, "宋体", Arial, sans-serif;
    --mf-font-mono: Consolas, "Courier New", Courier, monospace;
    --mf-title-size: 13px;
    --mf-body-size: 13px;
    --mf-body-line: 1.75;
    --mf-meta-size: 11.5px;
    --mf-comment-size: 13px;

    /* ---------- 尺寸（原站 960 时代的信息密度） ---------- */
    --mf-radius: 0;                  /* 门户零圆角 */
    --mf-chat-gap: 8px;
    --mf-gutter: 10px;
    --mf-avatar: 24px;               /* 文章块标题条内的小方头像 */
    --mf-avatar-comment: 26px;       /* 评论项方头像 */
    --mf-titlebar-h: 30px;           /* tbox 标题条高度（原站 25px，字号放大后略高） */
    --mf-topbar-height: 34px;        /* 顶栏工具条 */

    /* ---------- 内嵌素材 ---------- */
    --mf-logo: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20152%2042%22%20width%3D%22152%22%20height%3D%2242%22%3E%3Cg%3E%3Cpath%20d%3D%22M8%2013C3%208%202%203%206%201c2%205%205%208%208%2010z%22%20fill%3D%22%2300B0D8%22%2F%3E%3Cpath%20d%3D%22M20%2013c5-5%206-10%202-12-2%205-5%208-8%2010z%22%20fill%3D%22%23FF0080%22%2F%3E%3Ccircle%20cx%3D%2214%22%20cy%3D%2221%22%20r%3D%2210%22%20fill%3D%22%234CAF50%22%2F%3E%3Crect%20x%3D%229%22%20y%3D%2219%22%20width%3D%2210%22%20height%3D%223%22%20rx%3D%221.5%22%20fill%3D%22%23FFF%22%2F%3E%3C%2Fg%3E%3Cg%20font-family%3D%22Verdana%2CTahoma%2CArial%2Csans-serif%22%20font-weight%3D%22bold%22%3E%3Ctext%20x%3D%2230%22%20y%3D%2230%22%20font-size%3D%2227%22%20fill%3D%22%234CAF50%22%20textLength%3D%2232%22%20lengthAdjust%3D%22spacingAndGlyphs%22%3EMi%3C%2Ftext%3E%3Ctext%20x%3D%2263%22%20y%3D%2230%22%20font-size%3D%2227%22%20fill%3D%22%2300B0D8%22%20textLength%3D%2238%22%20lengthAdjust%3D%22spacingAndGlyphs%22%3Eku%3C%2Ftext%3E%3Ctext%20x%3D%22102%22%20y%3D%2230%22%20font-size%3D%2220%22%20fill%3D%22%23FF0080%22%20font-style%3D%22italic%22%20textLength%3D%2247%22%20lengthAdjust%3D%22spacingAndGlyphs%22%3EFans%3C%2Ftext%3E%3C%2Fg%3E%3C%2Fsvg%3E");
    --mf-wordmark: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20120%2040%22%20width%3D%22120%22%20height%3D%2240%22%3E%3Cg%20font-family%3D%22Verdana%2CTahoma%2CArial%2Csans-serif%22%20font-weight%3D%22bold%22%3E%3Ctext%20x%3D%220%22%20y%3D%2228%22%20font-size%3D%2226%22%20fill%3D%22%234CAF50%22%20textLength%3D%2234%22%20lengthAdjust%3D%22spacingAndGlyphs%22%3EMi%3C%2Ftext%3E%3Ctext%20x%3D%2234%22%20y%3D%2228%22%20font-size%3D%2226%22%20fill%3D%22%2300B0D8%22%20textLength%3D%2238%22%20lengthAdjust%3D%22spacingAndGlyphs%22%3Eku%3C%2Ftext%3E%3Ctext%20x%3D%2274%22%20y%3D%2228%22%20font-size%3D%2219%22%20fill%3D%22%23FF0080%22%20font-style%3D%22italic%22%20textLength%3D%2244%22%20lengthAdjust%3D%22spacingAndGlyphs%22%3Efans%3C%2Ftext%3E%3C%2Fg%3E%3C%2Fsvg%3E");
    --mf-avatar-default: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2064%2064%22%20width%3D%2264%22%20height%3D%2264%22%3E%3Crect%20width%3D%2264%22%20height%3D%2264%22%20fill%3D%22%23F0F0F0%22%2F%3E%3Ccircle%20cx%3D%2232%22%20cy%3D%2224%22%20r%3D%2211%22%20fill%3D%22%23C9C9C9%22%2F%3E%3Cpath%20d%3D%22M10%2062c0-15%2010-22%2022-22s22%207%2022%2022z%22%20fill%3D%22%23C9C9C9%22%2F%3E%3Crect%20width%3D%2264%22%20height%3D%2264%22%20fill%3D%22none%22%20stroke%3D%22%23DDDDDD%22%20stroke-width%3D%222%22%2F%3E%3C%2Fsvg%3E");
    --mf-ic-bullet: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%204%204%22%20width%3D%224%22%20height%3D%224%22%3E%3Crect%20width%3D%224%22%20height%3D%224%22%20fill%3D%22%23709C5A%22%2F%3E%3C%2Fsvg%3E");
    --mf-ic-quote: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2018%2016%22%20width%3D%2218%22%20height%3D%2216%22%3E%3Cpath%20d%3D%22M7%2014V9q0-5%205-7l1%202q-3%201-3%204h2v6z%22%20fill%3D%22%23C5DDBC%22%2F%3E%3Cpath%20d%3D%22M0%2014V9q0-5%205-7l1%202q-3%201-3%204h2v6z%22%20fill%3D%22%23C5DDBC%22%2F%3E%3C%2Fsvg%3E");
    --mf-ic-search: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2016%2016%22%20width%3D%2216%22%20height%3D%2216%22%3E%3Ccircle%20cx%3D%226.5%22%20cy%3D%226.5%22%20r%3D%225%22%20fill%3D%22none%22%20stroke%3D%22%23666666%22%20stroke-width%3D%221.6%22%2F%3E%3Cpath%20d%3D%22M10.4%2010.4%2015%2015%22%20stroke%3D%22%23666666%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%2F%3E%3C%2Fsvg%3E");
    --mf-ic-close: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2012%2012%22%20width%3D%2212%22%20height%3D%2212%22%3E%3Cpath%20d%3D%22M1%201l10%2010M11%201L1%2011%22%20stroke%3D%22%23666666%22%20stroke-width%3D%221.6%22%20stroke-linecap%3D%22round%22%2F%3E%3C%2Fsvg%3E");
    --mf-ic-more: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2018%204%22%20width%3D%2218%22%20height%3D%224%22%3E%3Ccircle%20cx%3D%222%22%20cy%3D%222%22%20r%3D%221.6%22%20fill%3D%22%23888888%22%2F%3E%3Ccircle%20cx%3D%229%22%20cy%3D%222%22%20r%3D%221.6%22%20fill%3D%22%23888888%22%2F%3E%3Ccircle%20cx%3D%2216%22%20cy%3D%222%22%20r%3D%221.6%22%20fill%3D%22%23888888%22%2F%3E%3C%2Fsvg%3E");
    --mf-ic-arrow-left: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%208%2012%22%20width%3D%228%22%20height%3D%2212%22%3E%3Cpath%20d%3D%22M7%201%201%206l6%205z%22%20fill%3D%22%23666666%22%2F%3E%3C%2Fsvg%3E");
    --mf-ic-arrow-right: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%208%2012%22%20width%3D%228%22%20height%3D%2212%22%3E%3Cpath%20d%3D%22M1%201l6%205-6%205z%22%20fill%3D%22%23666666%22%2F%3E%3C%2Fsvg%3E");
    --mf-ic-totop: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2014%2014%22%20width%3D%2214%22%20height%3D%2214%22%3E%3Cpath%20d%3D%22M7%201%201%208h4v5h4V8h4z%22%20fill%3D%22%23666666%22%2F%3E%3C%2Fsvg%3E");

    /* ---------- 覆盖 SillyTavern 内建中性色 ----------
     * 酒馆默认按深色底写了一批半透明黑/白与灰阶，浅色门户上会糊成一片灰带，
     * 这里把灰度值改到各自的对应档位，内建组件就会自动变浅。
     */
    --black30a: #F4F8EE;
    --black50a: rgba(197, 221, 188, 0.5);
    --black60a: rgba(197, 221, 188, 0.7);
    --white30a: #FFFFFF;
    --white50a: #FFFFFF;
    --grey10: #FCFDFA;
    --grey30: #F4F8EE;
    --grey50: #C5DDBC;
    --grey7070a: rgba(153, 153, 153, 0.45);
    /* 头像一律方角：原站所有头像是 52×52 的 1px 边框方块 */
    --avatar-base-border-radius-round: 0;

    /* ---------- 顶栏尺寸 ---------- */
    --topBarIconSize: 15px;
    --topBarBlockPadding: 4px;
    /* 酒馆用它算 #sheld 的 top，必须与实际顶栏高度一致，否则内容会钻到顶栏下面 */
    --topBarBlockSize: var(--mf-topbar-height);

    /* ---------- 兼容别名 ----------
     * pink 骨架里的分片直接引用了 --bl-*，这里映射一份，
     * 便于从其它变体搬片段过来时不改颜色。mikufans 自己的分片统一用 --mf-*。
     */
    --bl-pink: var(--mf-green);
    --bl-pink-hover: var(--mf-green);
    --bl-pink-soft: var(--mf-green-bg-2);
    --bl-blue: var(--mf-link);
    --bl-blue-deep: var(--mf-link);
    --bl-blue-soft: var(--mf-green-bg);
    --bl-dialogue: var(--mf-brand-pink);
    --bl-text-1: var(--mf-ink);
    --bl-text-2: var(--mf-ink-2);
    --bl-text-3: var(--mf-ink-4);
    --bl-line: var(--mf-line);
    --bl-line-soft: var(--mf-line-2);
    --bl-bg-1: var(--mf-paper);
    --bl-bg-2: var(--mf-green-bg);
    --bl-bg-3: var(--mf-paper-2);
    --bl-bg-sky: var(--mf-paper);
    --bl-font: var(--mf-font);
    --bl-font-mono: var(--mf-font-mono);
    --bl-radius: 0;
    --bl-radius-sm: 0;
    --bl-radius-pill: 0;
    --bl-shadow-card: none;
    --bl-shadow-float: none;
    --bl-ease: 120ms linear;
}


/*
 * 背景层：2009 年的白纸底。
 *
 * 原站是纯白页面 + 顶部一条浅绿装饰带，没有任何插画。
 * 这里保留纯白，只在极低对比度上叠一层 1px 横向参考线（间距 26px），
 * 模拟旧网页那种「表格辅助线」的印刷感——几乎看不见，但密度上更像门户。
 */

#bg1,
#bg_custom {
    position: fixed;
    inset: 0;
    width: 100% !important;
    height: 100% !important;
    background-color: var(--mf-paper) !important;
    background-image:
        /* 顶部装饰带：与原站 header 下方那条浅绿渐变对应 */
        linear-gradient(180deg, var(--mf-green-bg) 0%, rgba(244, 248, 238, 0) 120px),
        /* 1px 横向参考线 */
        repeating-linear-gradient(
            180deg,
            rgba(197, 221, 188, 0.22) 0 1px,
            transparent 1px 26px
        ) !important;
    background-repeat: no-repeat, repeat !important;
    background-position: left top, left top !important;
    background-size: 100% 120px, 100% 26px !important;
    background-attachment: scroll !important;
    filter: none !important;
}

/* 不用伪元素叠动画：原站是静态页面，动效全部收掉 */
#bg1::before,
#bg1::after,
#bg_custom::before,
#bg_custom::after {
    content: none !important;
}


/*
 * 门户装饰字形：不引入 bilibili 的图标字体，全部用自绘 SVG 与文字排版承担。
 * 这里只放「装饰性内容」，布局尺寸写在各层自己的分片里。
 */

/* AI 文章块底部工具行：原站内容页脚那排灰字链接 */
#chat .mes[is_user="false"] .mes_block::after {
    content: "分享　收藏　举报　·　本文由 Mikufans 整理";
}

/* 用户评论底部工具行 */
#chat .mes[is_user="true"] .mes_block::after {
    content: "赞　回复";
}

/* 打字指示器：方块闪动点（原站没有动效，用静态方块 + 灰字） */
#typing_indicator::before {
    content: "";
    display: inline-block;
    width: 7px;
    height: 7px;
    margin-right: 5px;
    background-color: var(--mf-title-2);
    vertical-align: 1px;
}

/* 加载文案左侧的小方块 */
#loading_mes::before {
    content: "";
    display: inline-block;
    width: 7px;
    height: 7px;
    margin-right: 6px;
    background-color: var(--mf-title-2);
    vertical-align: 1px;
}

/* 翻页箭头：给酒馆里出现的「上一页 / 下一页」类按钮统一成三角图标 */
.swipe_left::before,
.swipe_right::before {
    content: "";
    display: block;
    width: 6px;
    height: 10px;
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
}

.swipe_left::before {
    background-image: var(--mf-ic-arrow-left);
}

.swipe_right::before {
    background-image: var(--mf-ic-arrow-right);
}


/*
 * 默认头像：酒馆在「角色未设头像」时用 img/ai4.png（用户用 user-default.png），
 * 那是一张黑色剪影加问号。这里用 content 把 <img> 的显示内容换成主题自带的方角剪影，
 * 不改酒馆本体文件，也不影响任何已经设了自定义头像的角色。
 *
 * src 用包含匹配，覆盖 img/ai4.png、/img/ai4.png、缩略图 404 后回退等各种写法。
 */

img[src*="ai4.png"],
img[src*="user-default.png"] {
    content: var(--mf-avatar-default);
}

/* 少数地方把默认头像写成容器的内联背景图，一并覆盖 */
.avatar[style*="ai4.png"],
.avatar[style*="user-default.png"] {
    background-image: var(--mf-avatar-default) !important;
    background-size: cover;
    background-position: center;
    border-radius: 0;
}


/*
 * 框架层：全局排版、顶栏工具条、站名字标、红色小按钮、侧栏标题条、滚动条。
 * 目标观感：白纸底 + 1px 实线 + 浅绿标题条，零圆角、零阴影、零毛玻璃。
 */

/* ---------- 全局 ---------- */
body {
    font-family: var(--mf-font) !important;
    background-color: var(--mf-paper) !important;
    background-image: none !important;
    color: var(--mf-ink);
    /* 旧网页没有字间距，字号小、行距紧 */
    letter-spacing: 0;
    -webkit-font-smoothing: auto;
    -moz-osx-font-smoothing: auto;
}

textarea,
input,
select,
pre,
code,
.edit_textarea {
    font-family: var(--mf-font);
}

::selection {
    background-color: var(--mf-green-bg-2);
    color: var(--mf-green-deep);
}

/* 全站零圆角、零阴影：从根上掐掉酒馆内建的圆角与投影 */
:root {
    --SmartThemeShadowColor: transparent;
    --SmartThemeBlurStrength: 0;
}

/* ---------- 顶栏（工具条） ---------- */
#top-bar {
    position: relative;
    /* 酒馆用 --bottomFormBlockSize 算顶栏高度，这里统一到门户工具条高度 */
    height: var(--mf-topbar-height) !important;
    background-color: var(--mf-paper);
    background-image: linear-gradient(180deg, #FFFFFF 0%, #F9FCF5 100%);
    border-bottom: 1px solid var(--mf-line);
    border-radius: 0;
    box-shadow: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    z-index: 3005;
}

/* 顶栏底部那条 2px 绿色渐变，对应原站主导航条的下沿压线 */
#top-bar::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: -1px;
    height: 2px;
    background-image: linear-gradient(180deg, var(--mf-titlebar-b), var(--mf-line));
    pointer-events: none;
}

#top-settings-holder {
    background: transparent;
    border: none;
    box-shadow: none;
    border-radius: 0;
    color: var(--mf-ink-2);
    /* 左侧给字标让位，右侧给红色按钮让位，否则会压住顶栏图标 */
    padding: 0 88px 0 96px;
}

/* 左上角站名：MiKuFans 三色字标（矢量内嵌，随字号缩放） */
#top-settings-holder::before {
    content: "";
    position: absolute;
    left: 8px;
    top: 50%;
    width: 80px;
    height: 22px;
    transform: translateY(-50%);
    background-image: var(--mf-logo);
    background-repeat: no-repeat;
    background-position: left center;
    background-size: auto 22px;
    pointer-events: none;
}

/* 顶栏图标：默认 0.3 透明度在浅底上几乎看不见，提到 0.75 并改成绿色悬停 */
.drawer-icon.closedIcon,
.drawer-icon.openIcon {
    color: var(--mf-ink-2);
    opacity: 0.75;
    border-radius: 0;
    border: 1px solid transparent;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    .drawer-icon.closedIcon:hover {
        color: var(--mf-green);
        opacity: 1;
        background-color: var(--mf-green-bg-2);
        border-color: var(--mf-line-2);
    }
}

.drawer-icon:focus-visible {
    outline: 1px dotted var(--mf-green);
    outline-offset: -2px;
}

.drawer-icon.openIcon {
    color: var(--mf-green);
    opacity: 1;
    background-color: var(--mf-green-bg);
    border-color: var(--mf-line);
}

/* 顶栏右侧的角色快捷切换条 */
.hotswap,
.hotswap.closedIcon {
    color: var(--mf-ink-2);
    opacity: 0.75;
}

@media (hover: hover) and (pointer: fine) {
    .hotswap:hover {
        color: var(--mf-green);
        opacity: 1;
    }
}

/*
 * 右上角红按钮：复用酒馆原生的「角色管理」按钮（#rightNavDrawerIcon），只换皮，
 * 这样整块可点、点了就是原来那个面板，功能不丢。
 * 造型照搬原站搜索按钮：22px 高的红底直角块。
 */
#rightNavHolder > .drawer-toggle {
    position: absolute;
    right: 10px;
    top: 50%;
    transform: translateY(-50%);
    display: block;
}

#rightNavDrawerIcon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: auto;
    height: 22px;
    padding: 0 12px;
    border: 1px solid #9E0000;
    border-radius: 0;
    background-color: var(--mf-red);
    background-image: linear-gradient(180deg, #D82020 0%, var(--mf-red) 55%, #A80000 100%);
    color: #FFFFFF;
    opacity: 1;
    box-shadow: none;
    cursor: pointer;
    user-select: none;
    transition: none;
}

/* 去掉 FontAwesome 的角色卡片字形，换成「角色」两个字 */
#rightNavDrawerIcon::before {
    content: none;
}

#rightNavDrawerIcon::after {
    content: "角色";
    font-family: var(--mf-font);
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 1px;
}

@media (hover: hover) and (pointer: fine) {
    #rightNavDrawerIcon:hover {
        background-color: var(--mf-red-hover);
        background-image: linear-gradient(180deg, #EC3A3A 0%, var(--mf-red-hover) 55%, #B80000 100%);
        color: #FFFFFF;
        opacity: 1;
    }
}

/* 按下：用 1px 内阴影压出「陷进去」的旧网页手感 */
#rightNavDrawerIcon:active {
    background-image: none;
    background-color: #A80000;
    box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.45);
}

#rightNavDrawerIcon:focus-visible {
    outline: 1px dotted var(--mf-green-deep);
    outline-offset: 2px;
}

/* ---------- 左右侧栏 / 抽屉 ---------- */
#left-nav-panel,
#right-nav-panel {
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-line);
    box-shadow: 2px 2px 0 rgba(197, 221, 188, 0.55);
}

#left-nav-panel .drawer-content,
#right-nav-panel .drawer-content {
    background-color: var(--mf-paper);
}

/* 聊天主列：宽度与位置交给酒馆的「页面宽度」参数，主题不插手 */
#sheld {
    background-color: transparent;
    border: none;
    box-shadow: none;
}

.drawer-content {
    background-color: var(--mf-paper);
    border-color: var(--mf-line);
    border-radius: 0;
    color: var(--mf-ink);
    /* 宽度不覆盖：跟随酒馆「页面宽度」参数（--sheldWidth），与主体天然同宽 */
}

/* ---------- 侧栏分组标题：dl.tbox 的绿标题条 ----------
 * 酒馆给 `.standoutHeader` 铺了一条 348° 的深灰渐变（配深色主题用），
 * 两者特异性同为 (0,1,0) 且酒馆的样式表在 custom-style 之后生效，
 * 所以这里加 body 前缀把特异性提到 (0,1,1)，否则会出现「浅绿底 + 灰渐变」的脏色。
 */
body .standoutHeader {
    position: relative;
    color: var(--mf-title);
    font-weight: 700;
    font-size: 12px;
    line-height: 20px;
    letter-spacing: 1px;
    padding: 2px 8px 2px 10px;
    margin-bottom: 6px;
    background-color: var(--mf-titlebar-b);
    background-image: linear-gradient(180deg, var(--mf-titlebar-t) 0%, var(--mf-titlebar-b) 100%);
    border: 1px solid var(--mf-line);
    border-bottom-color: #B9D4AF;
    border-radius: 0;
}

/* 标题条左端那道深绿竖条 */
.standoutHeader::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 3px;
    background-color: var(--mf-title);
}

/* 折叠抽屉标题：同一套标题条造型 */
.inline-drawer-header,
.inline-drawer-toggle.inline-drawer-header {
    color: var(--mf-title);
    font-weight: 700;
    font-size: 12px;
    letter-spacing: 1px;
    border: 1px solid var(--mf-line);
    border-radius: 0;
    background-color: var(--mf-titlebar-b);
    background-image: linear-gradient(180deg, var(--mf-titlebar-t) 0%, var(--mf-titlebar-b) 100%);
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    .inline-drawer-header:hover,
    .inline-drawer-toggle.inline-drawer-header:hover {
        background-image: none;
        background-color: var(--mf-green-bg-2);
        color: var(--mf-green-deep);
    }
}

.inline-drawer-icon {
    color: var(--mf-ink-4);
}

/* ---------- 滚动条：老式方角滑块 ---------- */
::-webkit-scrollbar {
    width: 11px;
    height: 11px;
}

::-webkit-scrollbar-track {
    background: var(--mf-green-bg);
    border-left: 1px solid var(--mf-line-2);
}

::-webkit-scrollbar-thumb {
    background-color: var(--mf-line);
    border: 1px solid #AFCB9F;
    border-radius: 0;
}

@media (hover: hover) and (pointer: fine) {
    ::-webkit-scrollbar-thumb:hover {
        background-color: #B4D3A6;
    }
}

/* ---------- 聊天区容器 ---------- */
#chat {
    background-color: var(--mf-green-bg);
    /* 卡片保持全宽，左右留白放在卡片内部 */
    padding: 6px 0 8px;
}


/*
 * 内容层（上）：AI 消息 = DedeCMS 的 dl.tbox 内容块
 *
 * 结构照搬原站 side box：
 *   dt（浅绿渐变标题条：作者名 + 时间 + 右端操作）→ dd（白身正文）
 * 所以卡片自身不设内边距，标题条才能顶到 1px 外框的左右边。
 */

/* ---------- 内容块外框 ---------- */
#chat .mes[is_user="false"] {
    position: relative;
    display: block;
    width: 100%;
    align-self: center;
    margin: 0 auto var(--mf-chat-gap);
    padding: 0;
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    box-shadow: none;
}

/* ---------- 标题条 ---------- */
#chat .mes[is_user="false"] .ch_name {
    position: relative;
    display: flex;
    align-items: center;
    gap: 6px;
    min-height: var(--mf-titlebar-h);
    /* 左 42px 给绝对定位的小方头像，右侧留给操作按钮 */
    padding: 2px 6px 2px 42px;
    margin: 0;
    background-color: var(--mf-titlebar-b);
    background-image: linear-gradient(180deg, var(--mf-titlebar-t) 0%, var(--mf-titlebar-b) 100%);
    border-bottom: 1px solid var(--mf-line);
    /* 左端深绿竖条：原站标题条左侧的实心色块 */
    border-left: 3px solid var(--mf-title);
    border-top: none;
    border-right: none;
}

#chat .mes[is_user="false"] .name_text {
    font-size: var(--mf-title-size);
    font-weight: 700;
    line-height: 1.4;
    color: var(--mf-title);
    letter-spacing: 1px;
    word-break: break-word;
}

/* 标题条右侧的时间：原站 .tbox dt span.more 的浅绿灰字 */
#chat .mes .timestamp {
    margin-left: 8px;
    font-size: var(--mf-meta-size);
    color: var(--mf-title-2);
    font-variant-numeric: tabular-nums;
}

#chat .mes .mesIDDisplay,
#chat .mes .tokenCounterDisplay,
#chat .mes .mes_timer {
    color: var(--mf-ink-4);
    font-size: 11px;
}

/* ---------- 作者头像：标题条左侧的小方块 ---------- */
#chat .mes[is_user="false"] .mesAvatarWrapper {
    position: absolute;
    top: 3px;
    left: 8px;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: center;
    width: var(--mf-avatar);
    height: var(--mf-avatar);
    padding: 0;
    box-sizing: content-box;
}

#chat .mes[is_user="false"] .mesAvatarWrapper .avatar {
    width: var(--mf-avatar);
    height: var(--mf-avatar);
    box-sizing: border-box;
    padding: 1px;
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-frame-2);
    border-radius: 0;
    overflow: hidden;
    box-shadow: none;
    cursor: pointer;
}

@media (hover: hover) and (pointer: fine) {
    #chat .mes[is_user="false"] .mesAvatarWrapper .avatar:hover {
        border-color: #999999;
    }
}

/*
 * 酒馆把 .avatar img 写死成 50×50 且自带 50% 圆角，
 * 容器缩成 24px 后方图会被裁成「不方的方」，这里让图片填满容器，
 * 裁切统一交给 .avatar（方角）。
 */
#chat .mes .mesAvatarWrapper .avatar img {
    display: block;
    width: 100%;
    height: 100%;
    border: none;
    border-radius: 0;
    box-shadow: none;
    object-fit: cover;
    object-position: center;
}

#chat .mes[is_user="false"] .mes_block {
    min-width: 0;
    padding-left: 0;
    padding-right: 0;
}

#chat .mes[is_user="false"]::after {
    content: none;
}

/* ---------- 正文排版 ---------- */
#chat .mes[is_user="false"] .mes_text {
    padding: 9px 12px 10px 12px;
    font-size: var(--mf-body-size);
    line-height: var(--mf-body-line);
    color: var(--mf-ink);
    word-break: break-word;
    overflow-wrap: anywhere;
}

#chat .mes_text p {
    margin: 0 0 0.75em;
}

#chat .mes_text p:last-child {
    margin-bottom: 0;
}

#chat .mes_text strong,
#chat .mes_text b {
    font-weight: 700;
    color: #000000;
}

#chat .mes_text em,
#chat .mes_text i {
    color: var(--mf-ink-2);
}

/* 对话引号内文字：原站正文里的强调用深粉 */
#chat .mes_text q {
    color: var(--mf-brand-pink);
}

/* 链接：原站蓝链接，悬停转红并加下划线 */
#chat .mes_text a {
    color: var(--mf-link);
    text-decoration: none;
    border-bottom: none;
}

@media (hover: hover) and (pointer: fine) {
    #chat .mes_text a:hover {
        color: var(--mf-link-hover);
        text-decoration: underline;
    }
}

/* 标题层级：门户小标题，前面挂一个绿色方块 */
#chat .mes_text h1,
#chat .mes_text h2,
#chat .mes_text h3,
#chat .mes_text h4 {
    position: relative;
    color: var(--mf-ink);
    font-weight: 700;
    line-height: 1.5;
    margin: 1.1em 0 0.5em;
    padding-left: 10px;
}

#chat .mes_text h1::before,
#chat .mes_text h2::before,
#chat .mes_text h3::before,
#chat .mes_text h4::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0.45em;
    width: 4px;
    height: 0.95em;
    background-color: var(--mf-title-2);
}

#chat .mes_text h1 { font-size: 1.3em; }
#chat .mes_text h2 { font-size: 1.16em; }
#chat .mes_text h3 { font-size: 1.06em; }

#chat .mes_text h1:first-child,
#chat .mes_text h2:first-child,
#chat .mes_text h3:first-child {
    margin-top: 0;
}

/* 引用：原站评论引用块 —— 浅绿底 + 左侧绿线 + 左上角引号 */
#chat .mes_text blockquote {
    margin: 0 0 0.8em;
    padding: 6px 10px 6px 26px;
    background-color: var(--mf-green-bg);
    border: 1px solid var(--mf-line-2);
    border-left: 3px solid var(--mf-title-2);
    border-radius: 0;
    color: var(--mf-ink-2);
    background-image: var(--mf-ic-quote);
    background-repeat: no-repeat;
    background-position: 8px 7px;
    background-size: 12px auto;
}

#chat .mes_text blockquote p:last-child {
    margin-bottom: 0;
}

/* 列表：方块项目符号（原站 ico-2.gif 的现代版） */
#chat .mes_text ul,
#chat .mes_text ol {
    margin: 0 0 0.8em;
    padding-left: 1.5em;
}

#chat .mes_text li {
    margin-bottom: 0.25em;
}

#chat .mes_text ul > li::marker {
    content: "";
    color: transparent;
}

#chat .mes_text ul > li {
    list-style: none;
    position: relative;
    padding-left: 12px;
}

#chat .mes_text ul > li::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0.72em;
    width: 4px;
    height: 4px;
    background-color: var(--mf-title-2);
}

#chat .mes_text ol > li::marker {
    color: var(--mf-title-2);
    font-weight: 700;
}

/* 行内代码 */
#chat .mes_text code {
    padding: 1px 4px;
    border: 1px solid var(--mf-line-2);
    background-color: var(--mf-green-bg);
    color: var(--mf-red);
    border-radius: 0;
    font-family: var(--mf-font-mono);
    font-size: 0.92em;
}

/* 代码块：仿原站「代码示例」灰白块 */
#chat .mes_text pre {
    margin: 0 0 0.8em;
    padding: 8px 10px;
    background-color: var(--mf-paper-2);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    overflow-x: auto;
}

#chat .mes_text pre code {
    padding: 0;
    border: none;
    background: transparent;
    color: var(--mf-ink);
    font-size: 12.5px;
    line-height: 1.7;
}

/* 分割线：原站的虚线分隔 */
#chat .mes_text hr {
    height: 0;
    border: none;
    border-top: 1px dashed var(--mf-dash);
    margin: 1em 0;
}

/* 表格：1px 实线 + 浅绿表头，原站内容表格的样式 */
#chat .mes_text table {
    width: 100%;
    margin: 0 0 0.8em;
    border-collapse: collapse;
    font-size: 0.95em;
}

#chat .mes_text th,
#chat .mes_text td {
    padding: 4px 8px;
    border: 1px solid var(--mf-line);
    text-align: left;
}

#chat .mes_text th {
    background-color: var(--mf-green-bg);
    color: var(--mf-title);
    font-weight: 700;
}

#chat .mes_text tr:nth-child(even) td {
    background-color: var(--mf-paper-2);
}

/* ---------- 标题条里的操作按钮 ---------- */
#chat .mes .mes_button {
    color: var(--mf-title-2);
    opacity: 1;
    border-radius: 0;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    #chat .mes .mes_button:hover {
        color: var(--mf-green-deep);
        background-color: rgba(255, 255, 255, 0.7);
    }
}

#chat .mes .mes_button:active {
    color: var(--mf-green-deep);
    background-color: rgba(197, 221, 188, 0.6);
}

#chat .mes .mes_button:focus-visible {
    outline: 1px dotted var(--mf-green);
    outline-offset: 0;
}

#chat .mes .mes_buttons {
    opacity: 0.5;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    #chat .mes:hover .mes_buttons {
        opacity: 1;
    }
}

@media (hover: none) {
    #chat .mes .mes_buttons {
        opacity: 1;
    }
}

/* ---------- 推理块（思考过程）：折叠的注释小框 ---------- */
#chat .mes_reasoning_details {
    margin: 0 12px 8px;
    padding: 6px 8px;
    background-color: var(--mf-green-bg);
    border: 1px dashed var(--mf-dash);
    border-radius: 0;
}

#chat .mes_reasoning_header,
#chat .mes_reasoning_header_title {
    color: var(--mf-title-2);
    font-size: 12px;
    font-weight: 700;
}

#chat .mes_reasoning {
    color: var(--mf-ink-2);
    font-size: 12.5px;
    line-height: 1.7;
}

/* 楼层里插入的图片 / 附件：1px 图框 + 2px 白衬（原站 .e1 img 的画框） */
#chat .mes_media_wrapper img,
#chat .mes_file_wrapper img {
    border: 1px solid var(--mf-frame);
    border-radius: 0;
    padding: 2px;
    background-color: var(--mf-paper);
}

/* 底部操作行插槽：由 05-portal-glyphs.css 填充内容 */
#chat .mes[is_user="false"] .mes_block::after {
    display: block;
    margin: 0 12px 8px;
    padding-top: 6px;
    border-top: 1px dashed var(--mf-dash);
    font-size: 11px;
    line-height: 1.6;
    color: var(--mf-ink-4);
    letter-spacing: 0;
    user-select: none;
}


/*
 * 内容层（下）：用户消息 = 评论区的 .f2 列表项
 * 虚线上下分隔、方头像、蓝昵称、灰时间、左上角引号。
 * 不做卡片外框——评论在门户里就是「一条条排在内容块下面」的。
 */

#chat .mes[is_user="true"] {
    position: relative;
    display: block;
    width: 100%;
    align-self: center;
    margin: 0 auto 4px;
    padding: 6px 12px 8px;
    background-color: var(--mf-green-bg-2);
    border: none;
    border-top: 1px dashed var(--mf-dash);
    border-bottom: 1px dashed var(--mf-dash);
    border-radius: 0;
    box-shadow: none;
}

@media (hover: hover) and (pointer: fine) {
    #chat .mes[is_user="true"]:hover {
        background-color: #F5F8E6;
    }
}

/* 评论者头像：方角小图，贴昵称行左侧 */
#chat .mes[is_user="true"] .mesAvatarWrapper {
    position: absolute;
    top: 6px;
    left: 12px;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: center;
    width: var(--mf-avatar-comment);
    height: var(--mf-avatar-comment);
    padding: 0;
    box-sizing: content-box;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
    width: var(--mf-avatar-comment);
    height: var(--mf-avatar-comment);
    box-sizing: border-box;
    padding: 1px;
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-frame-2);
    border-radius: 0;
    overflow: hidden;
    box-shadow: none;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar img {
    display: block;
    width: 100%;
    height: 100%;
    border: none;
    border-radius: 0;
    object-fit: cover;
}

#chat .mes[is_user="true"] .mes_block {
    min-width: 0;
    padding-left: 0;
    padding-right: 0;
}

#chat .mes[is_user="true"]::after {
    content: none;
}

/* 昵称行：蓝链接 + 灰色时间 */
#chat .mes[is_user="true"] .ch_name {
    display: flex;
    align-items: center;
    gap: 6px;
    min-height: var(--mf-avatar-comment);
    padding-left: 36px;
    margin-bottom: 2px;
    border-bottom: none;
}

#chat .mes[is_user="true"] .name_text {
    font-size: 12px;
    font-weight: 700;
    line-height: 1.5;
    color: var(--mf-link);
    letter-spacing: 0;
}

#chat .mes[is_user="true"] .timestamp {
    font-size: 11px;
    color: var(--mf-ink-4);
    margin-left: 6px;
    font-variant-numeric: tabular-nums;
}

/* 评论正文：左上角引号 + 缩进，照原站 .f2 p */
#chat .mes[is_user="true"] .mes_text {
    padding: 1px 0 0 16px;
    font-size: var(--mf-comment-size);
    line-height: 1.7;
    color: var(--mf-ink);
    word-break: break-word;
    overflow-wrap: anywhere;
    background-image: var(--mf-ic-quote);
    background-repeat: no-repeat;
    background-position: 0 5px;
    background-size: 10px auto;
}

#chat .mes[is_user="true"] .mes_text p {
    margin: 0 0 0.5em;
}

#chat .mes[is_user="true"] .mes_text p:last-child {
    margin-bottom: 0;
}

#chat .mes[is_user="true"] .mes_text blockquote {
    margin: 0 0 0.5em;
    padding: 4px 8px;
    background-color: rgba(255, 255, 255, 0.8);
    border: 1px solid var(--mf-line-2);
    border-left: 2px solid var(--mf-title-2);
    border-radius: 0;
    color: var(--mf-ink-2);
}

#chat .mes[is_user="true"] .mes_text code {
    padding: 1px 3px;
    border: 1px solid var(--mf-line-2);
    background-color: rgba(255, 255, 255, 0.85);
    color: var(--mf-red);
    border-radius: 0;
    font-family: var(--mf-font-mono);
    font-size: 0.92em;
}

#chat .mes[is_user="true"] .mes_text pre {
    margin: 0 0 0.5em;
    padding: 6px 8px;
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    overflow-x: auto;
}

#chat .mes[is_user="true"] .mes_text pre code {
    border: none;
    background: transparent;
    padding: 0;
    color: var(--mf-ink);
}

#chat .mes[is_user="true"] .mes_text a {
    color: var(--mf-link);
    text-decoration: none;
}

@media (hover: hover) and (pointer: fine) {
    #chat .mes[is_user="true"] .mes_text a:hover {
        color: var(--mf-link-hover);
        text-decoration: underline;
    }
}

/* 评论底部装饰行由 05-portal-glyphs.css 填充 */
#chat .mes[is_user="true"] .mes_block::after {
    display: block;
    margin-top: 4px;
    padding-left: 16px;
    font-size: 11px;
    line-height: 1.5;
    color: var(--mf-ink-5);
    letter-spacing: 1px;
    user-select: none;
}

/* 右侧滑动切换块 */
#chat .mes .swipeRightBlock {
    color: var(--mf-ink-4);
}

#chat .mes .swipe_left,
#chat .mes .swipe_right {
    color: var(--mf-ink-4);
    border-radius: 0;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    #chat .mes .swipe_left:hover,
    #chat .mes .swipe_right:hover {
        color: var(--mf-green);
    }
}

#chat .mes .swipe_left:active,
#chat .mes .swipe_right:active {
    opacity: 0.7;
}

#chat .mes .swipe_left:focus-visible,
#chat .mes .swipe_right:focus-visible {
    outline: 1px dotted var(--mf-green);
    outline-offset: 0;
}

#chat .mes .swipes-counter {
    color: var(--mf-ink-4);
    font-size: 11px;
    font-variant-numeric: tabular-nums;
}

/* 选中的楼层：原站行高亮用浅绿 */
#chat .mes.selected {
    background-color: var(--mf-green-bg);
    outline: 1px solid var(--mf-line);
}


/*
 * 交互层（一）：输入区 = 站点搜索条
 *
 * 原站结构：40px 高的浅色条（.search）+ 内凹输入框（.ipt-txt）+ 红色小按钮。
 * 这里把输入区整条复刻成那个样子，左右按钮做成同高的方角小方块。
 */

#form_sheld {
    background-color: var(--mf-green-bg);
    border-top: 1px solid var(--mf-line-2);
    border-radius: 0;
    padding: 6px var(--mf-gutter) 8px;
}

#nonQRFormItems {
    display: flex;
    align-items: center;
    gap: 4px;
    width: 100%;
    margin: 0 auto;
    padding: 2px 4px;
    background-color: var(--mf-paper);
    /* 原站 .ipt-txt 的内凹边：上/左暗、下/右亮 */
    border: 1px solid;
    border-color: var(--mf-inset-t) var(--mf-inset-b) var(--mf-inset-b) var(--mf-inset-t);
    border-radius: 0;
    box-shadow: none;
    transition: none;
}

#nonQRFormItems:focus-within {
    border-color: var(--mf-green) var(--mf-inset-b) var(--mf-inset-b) var(--mf-green);
    box-shadow: none;
}

/* 输入框本体：无边框，视觉上就是内凹框里的一片白 */
#send_textarea {
    flex: 1 1 auto;
    min-width: 0;
    height: 24px;
    min-height: 24px;
    max-height: 40vh;
    padding: 2px 4px;
    margin: 0;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    color: var(--mf-ink);
    font-size: var(--mf-body-size);
    line-height: 20px;
    text-align: left;
    resize: none;
    outline: 1px solid transparent;
}

#send_textarea::placeholder {
    color: var(--mf-ink-5);
}

/* 酒馆内建样式会把输入文字/占位符居中，这里提高特异性改回左对齐 */
#form_sheld #send_textarea,
#form_sheld #send_textarea::placeholder {
    text-align: left;
}

/* ---------- 左右按钮组：同高方角小块 ---------- */
#leftSendForm,
#rightSendForm {
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    flex: 0 0 auto;
    width: max-content;
    min-width: 0;
    align-items: center;
    gap: 3px;
}

#options_button,
#leftSendForm .interactable {
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    width: 24px;
    height: 24px;
    min-width: 24px;
    padding: 0;
    border: 1px solid var(--mf-line-2);
    border-radius: 0;
    background-color: var(--mf-green-bg);
    color: var(--mf-ink-2);
    font-size: 12px;
    line-height: 1;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    #options_button:hover,
    #leftSendForm .interactable:hover {
        background-color: var(--mf-green-bg-2);
        border-color: var(--mf-line);
        color: var(--mf-green);
    }
}

#options_button:active,
#leftSendForm .interactable:active {
    background-color: var(--mf-line-2);
    box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.12);
    color: var(--mf-green-deep);
}

#options_button:focus-visible,
#leftSendForm .interactable:focus-visible {
    outline: 1px dotted var(--mf-green);
    outline-offset: 0;
}

/* ---------- 发送按钮：原站红色搜索按钮 ---------- */
#send_but:not(.displayNone) {
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    width: 40px;
    height: 24px;
    min-width: 40px;
    padding: 0;
    border: 1px solid #9E0000;
    border-radius: 0;
    background-color: var(--mf-red);
    background-image: linear-gradient(180deg, #D82020 0%, var(--mf-red) 55%, #A80000 100%);
    color: #FFFFFF;
    font-size: 12px;
    line-height: 1;
    cursor: pointer;
    box-shadow: none;
    transition: none;
}

/* 停止 / 继续 / 扮演：同一套红块，显隐仍由酒馆的 .displayNone 控制 */
#mes_continue,
#mes_impersonate,
#stscript_stop,
#stscript_continue,
#stscript_pause {
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    width: 40px;
    height: 24px;
    min-width: 40px;
    padding: 0;
    border: 1px solid #9E0000;
    border-radius: 0;
    background-color: var(--mf-red);
    background-image: linear-gradient(180deg, #D82020 0%, var(--mf-red) 55%, #A80000 100%);
    color: #FFFFFF;
    font-size: 12px;
    line-height: 1;
    cursor: pointer;
    box-shadow: none;
    transition: none;
}

/*
 * 停止按钮：尺寸与发送按钮对齐。酒馆用 --bottomFormBlockSize 定它的大小，
 * 这里直接锁同一组宽高，并去掉酒馆自带的 fa-circle-stop 字形，
 * 用绝对定位的白方块做「停止」符号。
 */
#mes_stop {
    position: relative;
    box-sizing: border-box;
    width: 40px !important;
    height: 24px !important;
    min-width: 0;
    padding: 0 !important;
    border: 1px solid #9E0000;
    border-radius: 0;
    background-color: var(--mf-red);
    background-image: linear-gradient(180deg, #D82020 0%, var(--mf-red) 55%, #A80000 100%);
    color: #FFFFFF;
    overflow: clip;
    cursor: pointer;
    box-shadow: none;
    transition: none;
}

#mes_stop i {
    display: none;
}

#mes_stop::after {
    content: "";
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: 9px;
    height: 9px;
    border-radius: 0;
    background-color: #FFFFFF;
}

@media (hover: hover) and (pointer: fine) {
    #send_but:not(.displayNone):hover,
    #mes_stop:not(.displayNone):hover,
    #mes_continue:not(.displayNone):hover,
    #mes_impersonate:not(.displayNone):hover,
    #stscript_stop:not(.displayNone):hover,
    #stscript_continue:not(.displayNone):hover,
    #stscript_pause:not(.displayNone):hover {
        background-image: linear-gradient(180deg, #EC3A3A 0%, var(--mf-red-hover) 55%, #B80000 100%);
    }
}

#send_but:not(.displayNone):active,
#mes_stop:not(.displayNone):active,
#mes_continue:not(.displayNone):active,
#mes_impersonate:not(.displayNone):active,
#stscript_stop:not(.displayNone):active,
#stscript_continue:not(.displayNone):active,
#stscript_pause:not(.displayNone):active {
    background-image: none;
    background-color: #A80000;
    box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.45);
}

#send_but:not(.displayNone):focus-visible,
#mes_stop:not(.displayNone):focus-visible,
#mes_continue:not(.displayNone):focus-visible,
#mes_impersonate:not(.displayNone):focus-visible,
#stscript_stop:not(.displayNone):focus-visible,
#stscript_continue:not(.displayNone):focus-visible,
#stscript_pause:not(.displayNone):focus-visible {
    outline: 1px dotted var(--mf-green-deep);
    outline-offset: 2px;
}

/* 生成中：停止按钮用更深的红区分，并保留极轻微的明暗呼吸 */
#mes_stop {
    animation: mf-stop-blink 1.4s steps(2, end) infinite;
}

@keyframes mf-stop-blink {
    0%, 100% { background-image: linear-gradient(180deg, #D82020 0%, var(--mf-red) 55%, #A80000 100%); }
    50% { background-image: none; background-color: #A00000; }
}

@media (prefers-reduced-motion: reduce) {
    #mes_stop:not(.displayNone) {
        animation: none;
    }
}

/*
 * 尺寸加固：酒馆的 `#rightSendForm>div:not(.mes_stop)` 带一个 class，
 * 特异性 (1,1,1) 高于单 id 的 (1,1,0)，会把上面的红块重新撑成 --bottomFormBlockSize
 * （实测被拉回到 34.5px 高，整条输入栏跟着变高）。
 * 这里用 id + 元素 + 容器把特异性提到 (2,1,0)，把右侧所有红块锁在同一组尺寸上。
 */
#rightSendForm > div#send_but,
#rightSendForm > div#mes_continue,
#rightSendForm > div#mes_impersonate,
#rightSendForm > div#stscript_stop,
#rightSendForm > div#stscript_continue,
#rightSendForm > div#stscript_pause {
    box-sizing: border-box;
    width: 40px;
    height: 24px;
    min-width: 40px;
    margin: 0;
    padding: 0;
    border: 1px solid #9E0000;
    border-radius: 0;
    background-color: var(--mf-red);
    background-image: linear-gradient(180deg, #D82020 0%, var(--mf-red) 55%, #A80000 100%);
    color: #FFFFFF;
    font-size: 12px;
    line-height: 1;
    /* 酒馆给右侧按钮 0.7 透明度，门户里实心红块更清楚 */
    opacity: 1;
    box-shadow: none;
}

#send_but::before {
    font-size: 12px;
}

/* ---------- 快捷回复：一排小方按钮 ---------- */
#qr--bar {
    margin: 0 auto 5px;
    padding: 0;
    background: transparent;
    color: var(--mf-ink-2);
}

#send_form #qr--bar {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    gap: 4px;
}

/* quick-reply 扩展的样式表在本主题之后加载，统一用 #form_sheld 提高特异性 */
#form_sheld #qr--bar > .qr--buttons {
    flex: 0 0 auto;
    width: auto;
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    gap: 4px;
    padding: 0;
}

#form_sheld #qr--bar > .qr--buttons .qr--button {
    max-width: 210px;
    padding: 2px 8px;
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    color: var(--mf-ink-2);
    font-size: 11.5px;
    line-height: 1.5;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    #form_sheld #qr--bar > .qr--buttons .qr--button:hover {
        border-color: var(--mf-green);
        background-color: var(--mf-green-bg-2);
        color: var(--mf-green);
    }
}

#form_sheld #qr--bar > .qr--buttons .qr--button:active {
    border-color: var(--mf-green);
    background-color: var(--mf-line-2);
    color: var(--mf-green-deep);
}

body #qr--popout > .qr--body {
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    box-shadow: 2px 2px 0 rgba(197, 221, 188, 0.55);
}

body #qr--popout > .qr--body > .qr--buttons .qr--button {
    max-width: 260px;
    padding: 3px 8px;
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    color: var(--mf-ink-2);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

@media (hover: hover) and (pointer: fine) {
    body #qr--popout > .qr--body > .qr--buttons .qr--button:hover {
        background-color: var(--mf-green-bg-2);
        border-color: var(--mf-green);
        color: var(--mf-green);
    }
}

body #qr--popout > .qr--body > .qr--buttons .qr--button:active {
    background-color: var(--mf-line-2);
    border-color: var(--mf-green);
    color: var(--mf-green-deep);
}

/* 附件预览条 */
#file_form .file_attached {
    border-radius: 0;
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-line);
}

/* 打字指示器文案 */
#typing_indicator {
    color: var(--mf-ink-4);
    font-size: var(--mf-meta-size);
}


/*
 * 交互层（二）：抽屉、设置面板、表单控件、菜单、提示
 * 统一为「绿标题条 + 白身 + 1px 实线」的 dl.tbox 块，控件一律直角。
 */

/* ---------- 面板与抽屉 ---------- */
.drawer-content,
#top-settings-holder .drawer-content,
#left-nav-panel .drawer-content,
#right-nav-panel .drawer-content {
    background-color: var(--mf-paper);
    border-color: var(--mf-line);
    border-radius: 0;
    color: var(--mf-ink);
}

.drawer-content .scrollableInner,
#left-nav-panel .scrollableInner,
#right-nav-panel .scrollableInner {
    scrollbar-width: thin;
}

/* 面板内部分隔：原站的虚线 */
#left-nav-panel hr,
#right-nav-panel hr,
.drawer-content hr {
    border: none;
    border-top: 1px dashed var(--mf-dash);
    margin: 8px 0;
}

/* ---------- 文本输入：原站 .ipt-txt 的内凹框 ---------- */
.text_pole,
textarea.text_pole,
input.text_pole,
input[type="text"],
input[type="search"],
input[type="number"],
input[type="password"] {
    background-color: var(--mf-paper);
    border: 1px solid;
    border-color: var(--mf-inset-t) var(--mf-inset-b) var(--mf-inset-b) var(--mf-inset-t);
    border-radius: 0;
    color: var(--mf-ink);
    font-size: 12px;
    transition: none;
}

.text_pole:focus,
textarea.text_pole:focus,
input[type="text"]:focus,
input[type="search"]:focus,
input[type="number"]:focus,
input[type="password"]:focus {
    outline: 1px solid var(--mf-green);
    outline-offset: -1px;
    border-color: var(--mf-green) var(--mf-inset-b) var(--mf-inset-b) var(--mf-green);
    box-shadow: none;
}

.text_pole::placeholder {
    color: var(--mf-ink-5);
}

/* 下拉框 */
select,
.text_pole.select,
.select2-container--default .select2-selection--single,
.select2-container--default .select2-selection--multiple {
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    color: var(--mf-ink);
    font-size: 12px;
}

.select2-container--default .select2-selection--single .select2-selection__rendered {
    color: var(--mf-ink);
}

/* 原生下拉的选项默认黑底白字（深色主题专用），白底主题里会突然黑一片 */
select option {
    background-color: var(--mf-paper);
    color: var(--mf-ink);
}

select option:not(:checked) {
    background-color: var(--mf-paper);
    color: var(--mf-ink);
}

select option:checked {
    background-color: var(--mf-green-bg-2);
    color: var(--mf-green-deep);
}

select option[disabled]:not(:checked) {
    color: var(--mf-ink-4);
}

.select2-dropdown {
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    box-shadow: 2px 2px 0 rgba(197, 221, 188, 0.55);
}

.select2-container--default .select2-results__option--highlighted[aria-selected] {
    background-color: var(--mf-green-bg-2);
    color: var(--mf-green);
}

/* 勾选框 / 滑块 / 单选 */
input[type="checkbox"],
input[type="radio"] {
    accent-color: var(--mf-green);
    border-radius: 0;
}

input[type="range"] {
    accent-color: var(--mf-green);
}

/* ---------- 按钮：原站 .btn-1 / .btn-2 的方块感 ---------- */
.menu_button,
.menu_button_icon {
    background-color: var(--mf-green-bg);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    color: var(--mf-ink-2);
    font-size: 12px;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    .menu_button:hover,
    .menu_button_icon:hover {
        background-color: var(--mf-green-bg-2);
        border-color: var(--mf-green);
        color: var(--mf-green);
    }
}

.menu_button:active,
.menu_button_icon:active {
    background-color: var(--mf-line-2);
    box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.12);
    border-color: var(--mf-green);
    color: var(--mf-green-deep);
}

.menu_button:focus-visible,
.menu_button_icon:focus-visible {
    outline: 1px dotted var(--mf-green-deep);
    outline-offset: 1px;
}

.menu_button.selected,
.menu_button.toggleEnabled {
    background-color: var(--mf-green);
    border-color: var(--mf-green-deep);
    color: #FFFFFF;
}

@media (hover: hover) and (pointer: fine) {
    .menu_button.selected:hover,
    .menu_button.toggleEnabled:hover {
        background-color: var(--mf-green-deep);
        color: #FFFFFF;
    }
}

/* 危险操作保持红色语义 */
.menu_button.danger {
    color: var(--mf-red);
}

@media (hover: hover) and (pointer: fine) {
    #delete_button:hover,
    #reset_button:hover {
        color: var(--mf-red);
        border-color: var(--mf-red);
    }
}

/* ---------- 角色列表 / 卡片条目 ---------- */
.character_select,
.group_select,
.character_select_container,
.entity_block {
    border-radius: 0;
    border-bottom: 1px dashed var(--mf-dash);
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    .character_select:hover,
    .group_select:hover {
        background-color: var(--mf-green-bg-2);
    }
}

.character_select:active,
.group_select:active {
    background-color: var(--mf-line-2);
}

.character_select:focus-visible,
.group_select:focus-visible {
    outline: 1px dotted var(--mf-green);
    outline-offset: -1px;
}

.character_name_block .ch_name,
.character_name_block .character_name {
    color: var(--mf-ink);
    font-weight: 700;
    font-size: 12.5px;
}

.character_name_block .character_file,
.character_name_block .group_file {
    color: var(--mf-ink-4);
    font-size: 11px;
}

/* 当前选中角色：浅绿条 + 左侧绿竖线 */
.character_select.is_selected,
.group_select.is_selected {
    background-color: var(--mf-green-bg);
    box-shadow: inset 3px 0 0 var(--mf-title);
}

/* ---------- 弹出菜单 / 弹层 ---------- */
#options,
.options-content,
.popup,
.dialogs,
#dialogue_popup {
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    box-shadow: 2px 2px 0 rgba(197, 221, 188, 0.6);
    color: var(--mf-ink);
}

#options .options-content a,
#options .options-content .interactable {
    border-radius: 0;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    #options .options-content a:hover,
    #options .options-content .interactable:hover {
        background-color: var(--mf-green-bg-2);
        color: var(--mf-green);
    }
}

#options .options-content a:active,
#options .options-content .interactable:active {
    background-color: var(--mf-line-2);
    color: var(--mf-green-deep);
}

/* 弹窗标题 */
.dialogue_popup_text h2,
.popup_title,
.dialogue_popup_controls h3 {
    color: var(--mf-ink);
}

/* ---------- 提示消息：白底 + 左侧 3px 色条 ----------
 * 酒馆原生给 .toast-success 之类铺了语义底色，权重比 #toast-container > div 高；
 * 只改边框会变成「绿底 + 我的边」的拼接感，所以整块接管。
 * 原生图标是透明底白色 PNG，放白底上等于消失 —— 关掉 background-image 并收回左侧内边距。
 */
body #toast-container > div.toast {
    background-color: var(--mf-paper);
    background-image: none;
    border: 1px solid var(--mf-line);
    border-left: 3px solid var(--mf-title-2);
    border-radius: 0;
    box-shadow: 2px 2px 0 rgba(197, 221, 188, 0.6);
    color: var(--mf-ink);
    font-size: 12px;
    opacity: 1;
    padding: 8px 10px 8px 12px;
    width: 300px;
}

body #toast-container > div.toast.toast-success {
    border-left-color: var(--mf-green);
}

body #toast-container > div.toast.toast-error {
    border-left-color: var(--mf-red);
}

body #toast-container > div.toast.toast-warning {
    border-left-color: var(--mf-accent);
}

body #toast-container > div.toast.toast-info {
    border-left-color: var(--mf-link);
}

/* ---------- 设置页分组标题：绿标题条 ---------- */
#user-settings-block h4,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
    background-image: linear-gradient(180deg, var(--mf-titlebar-t) 0%, var(--mf-titlebar-b) 100%);
    background-color: var(--mf-titlebar-b);
    border: 1px solid var(--mf-line);
    border-radius: 0;
    color: var(--mf-title);
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 1px;
}

@media (hover: hover) and (pointer: fine) {
    #user-settings-block h4:hover,
    #extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
    #extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover {
        filter: none;
        background-image: none;
        background-color: var(--mf-green-bg-2);
        color: var(--mf-green-deep);
    }
}

/*
 * 提示词管理器：类名带 completion_ 前缀（聊天补全）和不带前缀（文本补全）两套，
 * 用 [class*=] 一次覆盖；酒馆自己的规则是 #id #id 级别，这里必须 !important 才压得住。
 */
[class*="prompt_manager_prompt"] [class*="prompt_manager_prompt_name"],
[class*="prompt_manager_prompt_name"] .prompt-manager-inspect-action {
    color: var(--mf-ink) !important;
}

/* 启用中的开关用深绿 */
[class*="prompt_manager_prompt"]:not([class*="prompt_manager_prompt_disabled"]) .prompt-manager-toggle-action {
    color: var(--mf-green) !important;
}

/* 禁用项名称酒馆默认用 white30a（深色主题专用），白底上等于隐形 */
[class*="prompt_manager_prompt_disabled"] {
    border-color: var(--mf-line) !important;
    background-color: var(--mf-paper-2) !important;
}

[class*="prompt_manager_prompt_disabled"] [class*="prompt_manager_prompt_name"],
[class*="prompt_manager_prompt_disabled"] [class*="prompt_manager_prompt_name"] .prompt-manager-inspect-action {
    color: var(--mf-ink-5) !important;
}

/* 表头「名称 / Token」那行同样是 white50a */
[class*="prompt_manager_header"] {
    color: var(--mf-ink-4) !important;
}

/* 图标上的黑色投影是给深色底做的，浅底上去掉更干净 */
[class*="prompt_manager_prompt"] span span span,
[class*="prompt_manager_header_advanced"] span {
    filter: none;
}

/* 选中态：酒馆默认拿 SmartThemeQuoteColor 铺深色块，统一改成浅绿 */
.macroBrowser .macro-sort-btn.active,
.macroBrowser .macro-item.selected,
#rm_print_characters_block.group_overlay_mode_select .character_select.character_selected,
#bg_tabs .bg_tabs_list .bg_tab_button.ui-tabs-active {
    background-color: var(--mf-green-bg);
    border-color: var(--mf-line);
    color: var(--mf-ink);
}

/* ---------- 标签 / 徽章：小方块，浅绿底 ---------- */
.tag,
.tag_name,
.character_version,
.character_tag {
    border-radius: 0;
    background-color: var(--mf-green-bg);
    border: 1px solid var(--mf-line-2);
    color: var(--mf-ink-2);
    font-size: 11px;
}

@media (hover: hover) and (pointer: fine) {
    .tag:hover,
    .character_tag:hover {
        background-color: var(--mf-green-bg-2);
        border-color: var(--mf-line);
        color: var(--mf-green);
    }
}

.tag:active,
.character_tag:active {
    background-color: var(--mf-line-2);
    color: var(--mf-green-deep);
}


/*
 * 主页（欢迎面板）：按门户首页的列表思路重排。
 * 页头（站名 → 版本 → 工具按钮）→ 分类行（最近的聊天 + 快捷入口）→ 虚线列表。
 *
 * 酒馆 1.19 的「最近聊天」组件结构：
 *   .recentChat > .avatar + .recentChatInfo
 *   .recentChatInfo > .chatNameContainer(.chatName/.chatDate/.chatActions)
 *                   + .chatMessageContainer(.chatMessage/.chatStats)
 * 用 display: contents 摊平两个容器，凑出「封面 / 标题 / 摘要 / 元信息」四层。
 *
 * 注意：酒馆自带的 welcome.css 用的是 `.welcomeRecent .recentChatList .recentChat …`（三到四级类），
 * 这里必须保持同样的层级深度才压得住，不要简化选择器。
 */

/* ---------- 页头 ---------- */
.welcomePanel {
    background-color: transparent;
    border: none;
    border-radius: 0;
    box-shadow: none;
    padding: 0;
}

.welcomePanel .welcomeHeaderTitle {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 2px 8px;
    border-bottom: 1px solid var(--mf-line);
}

/* 页头左侧换成站名字标 */
.welcomePanel .welcomeHeaderLogo {
    width: 21px;
    height: 21px;
    border-radius: 0;
    flex: 0 0 auto;
    object-fit: contain;
}

.welcomePanel .welcomeHeaderVersionDisplay {
    font-size: 14px;
    font-weight: 700;
    color: var(--mf-title);
    letter-spacing: 1px;
}

.welcomePanel .welcomeHeaderTitle .mes_button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    margin-left: 2px;
    border: 1px solid var(--mf-line-2);
    border-radius: 0;
    background-color: var(--mf-green-bg);
    color: var(--mf-ink-2);
    opacity: 1;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeHeaderTitle .mes_button:hover {
        background-color: var(--mf-green-bg-2);
        border-color: var(--mf-line);
        color: var(--mf-green);
    }
}

.welcomePanel .welcomeHeaderTitle .mes_button:active {
    background-color: var(--mf-line-2);
    color: var(--mf-green-deep);
}

.welcomePanel .welcomeHeaderTitle .mes_button:focus-visible {
    outline: 1px dotted var(--mf-green);
    outline-offset: 1px;
}

/* ---------- 分类行 ---------- */
.welcomePanel .welcomeHeader {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px;
    padding: 8px 2px 6px;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 1px;
    color: var(--mf-title);
    border-bottom: 1px solid var(--mf-line);
}

/* 「最近的聊天」前面的绿色方块 */
.welcomePanel .welcomeHeader::before {
    content: "";
    flex: 0 0 auto;
    width: 4px;
    height: 12px;
    border-radius: 0;
    background-color: var(--mf-title-2);
}

.welcomePanel .welcomeShortcuts {
    display: flex;
    align-items: center;
    gap: 4px;
    margin-left: auto;
}

.welcomePanel .welcomeShortcuts .menu_button {
    height: 22px;
    padding: 0 8px;
    border: 1px solid var(--mf-line);
    border-radius: 0;
    background-color: var(--mf-green-bg);
    color: var(--mf-ink-2);
    font-size: 11.5px;
    font-weight: 400;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeShortcuts .menu_button:hover {
        background-color: var(--mf-green-bg-2);
        border-color: var(--mf-green);
        color: var(--mf-green);
    }
}

.welcomePanel .welcomeShortcuts .menu_button:active {
    background-color: var(--mf-line-2);
    color: var(--mf-green-deep);
}

.welcomePanel .welcomeShortcutsSeparator {
    display: none;
}

/* ---------- 列表 ---------- */
.welcomePanel .welcomeRecent {
    padding: 0 0 4px;
}

.welcomePanel .welcomeRecent .recentChatList {
    display: flex;
    flex-direction: column;
    gap: 0;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat {
    position: relative;
    display: grid;
    grid-template-columns: 52px minmax(0, 1fr);
    column-gap: 10px;
    align-items: start;
    padding: 7px 8px;
    border: none;
    border-bottom: 1px dashed var(--mf-dash);
    border-radius: 0;
    background-color: transparent;
    transition: none;
}

/* 折叠的条目必须真的不占位，否则「更多」按钮前会留一大片空白 */
.welcomePanel .welcomeRecent .recentChatList .recentChat.hidden {
    display: none;
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeRecent .recentChatList .recentChat:hover {
        background-color: var(--mf-green-bg-2);
        border-bottom-color: var(--mf-line);
    }
}

.welcomePanel .welcomeRecent .recentChatList .recentChat:focus-within {
    background-color: var(--mf-green-bg-2);
    outline: 1px dotted var(--mf-green);
    outline-offset: -1px;
}

/* 封面 = 角色头像，裁成 1px 白衬的方图（原站 .e1 img 的画框） */
.welcomePanel .welcomeRecent .recentChatList .recentChat .avatar {
    flex: 0 0 auto;
    align-self: start;
    width: 52px;
    height: 52px;
    margin: 0;
    box-sizing: border-box;
    padding: 1px;
    background-color: var(--mf-paper);
    border: 1px solid var(--mf-frame);
    border-radius: 0;
    overflow: hidden;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .avatar img {
    display: block;
    width: 100%;
    height: 100%;
    border-radius: 0;
    object-fit: cover;
}

/* 右侧内容摊平成三层：标题 / 摘要 / 元信息 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .recentChatInfo {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
        "name name"
        "preview preview"
        "date stats";
    align-items: center;
    align-self: start;
    gap: 2px 8px;
    min-width: 0;
    overflow: visible;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatNameContainer,
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatMessageContainer {
    display: contents;
}

/* 标题：原站列表链接的蓝转红 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatName {
    grid-area: name;
    flex: none;
    min-width: 0;
    padding-right: 76px; /* 给右上角的置顶/重命名/删除让位 */
    font-size: 12.5px;
    font-weight: 700;
    line-height: 1.45;
    color: var(--mf-ink);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatName .characterName {
    font-weight: 700;
    color: var(--mf-title);
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatName > span {
    font-size: 11.5px;
    font-weight: 400;
    color: var(--mf-ink-4);
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeRecent .recentChatList .recentChat:hover .chatName {
        color: var(--mf-link-hover);
    }

    .welcomePanel .welcomeRecent .recentChatList .recentChat:hover .chatName .characterName {
        color: var(--mf-link-hover);
    }
}

/* 摘要 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatMessage {
    grid-area: preview;
    font-size: 12px;
    line-height: 1.5;
    color: var(--mf-ink-3);
    word-break: break-word;
}

/* 元信息行：左时间、右数据 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatDate {
    grid-area: date;
    justify-self: start;
    margin: 0;
    font-size: 11px;
    color: var(--mf-ink-4);
    white-space: nowrap;
    font-variant-numeric: tabular-nums;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatStats {
    grid-area: stats;
    justify-self: end;
    align-self: center;
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 11px;
    color: var(--mf-ink-4);
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatStats .counterBlock {
    display: inline-flex;
    align-items: center;
    gap: 3px;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatStats .counterBlock::after {
    content: "·";
    margin-left: 3px;
    color: var(--mf-ink-5);
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatStats small {
    font-size: 11px;
    color: var(--mf-ink-4);
}

/* 操作按钮：平时隐形，悬停/聚焦才出现 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions {
    position: absolute;
    top: 6px;
    right: 6px;
    display: flex;
    gap: 2px;
    opacity: 0;
    transition: none;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat:focus-within .chatActions {
    opacity: 1;
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeRecent .recentChatList .recentChat:hover .chatActions {
        opacity: 1;
    }
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    margin: 0;
    padding: 0;
    border: 1px solid var(--mf-line-2);
    border-radius: 0;
    background-color: var(--mf-paper);
    color: var(--mf-ink-2);
    font-size: 11px;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions button:hover {
        background-color: var(--mf-green-bg-2);
        border-color: var(--mf-line);
        color: var(--mf-green);
    }
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions button:active {
    background-color: var(--mf-line-2);
    color: var(--mf-green-deep);
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions button:focus-visible {
    outline: 1px dotted var(--mf-green);
    outline-offset: 1px;
}

/* 「显示更多」：居中的小方块按钮，紧贴最后一条 */
.welcomePanel .welcomeRecent .recentChatList .showMoreChats {
    align-self: center;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 22px;
    margin: 6px 0 0;
    padding: 0;
    border: 1px solid var(--mf-line);
    border-radius: 0;
    background-color: var(--mf-green-bg);
    color: var(--mf-ink-2);
    font-size: 11px;
    transition: none;
}

@media (hover: hover) and (pointer: fine) {
    .welcomePanel .welcomeRecent .recentChatList .showMoreChats:hover {
        background-color: var(--mf-green-bg-2);
        border-color: var(--mf-green);
        color: var(--mf-green);
    }
}

.welcomePanel .welcomeRecent .recentChatList .showMoreChats:active {
    background-color: var(--mf-line-2);
    color: var(--mf-green-deep);
}

.welcomePanel .welcomeRecent .recentChatList .showMoreChats:focus-visible {
    outline: 1px dotted var(--mf-green);
    outline-offset: 1px;
}

/* 置顶标记换成绿色小三角 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .recentChatPinned {
    top: 1px;
    left: 1px;
    color: var(--mf-title-2);
    opacity: 1;
}

/* 触屏没有 hover，按钮常显 */
@media (hover: none) {
    .welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions {
        opacity: 1;
    }
}


/*
 * 加载页：接管 SillyTavern 的加载遮罩，复刻原站那句
 * 「正在载入,请稍候...」（连全角逗号一起搬）。
 *
 * 两条链路都要覆盖，否则切换时会闪一下默认样式：
 *   1. HTML 首屏的 <div id="preloader">（JS 还没跑起来时）
 *   2. 初始化后由 action-loader.js 创建的
 *      <dialog class="popup transparent_dialogue_popup"> 内的 #loader.splash-screen
 */

/* 站名字标：logo.svg 宽高比 152 / 42 ≈ 3.619 */
#preloader::before,
#loader #load-spinner {
    --mf-brand-h: 26px;
    --mf-brand-w: calc(var(--mf-brand-h) * 3.619);
}

/* ---------- 全屏遮罩 ---------- */
#preloader,
.popup.transparent_dialogue_popup:has(#loader) {
    background-color: var(--mf-green-bg);
    background-image: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}

/* 首屏还没创建 #loader 时，至少先给出站名 */
#preloader::before {
    content: "";
    position: absolute;
    left: 50%;
    top: 50%;
    width: var(--mf-brand-w);
    height: var(--mf-brand-h);
    transform: translate(-50%, -50%);
    background-image: var(--mf-logo);
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
}

/* 加载 Popup 本身：铺满视口、去掉弹窗边框与内边距 */
.popup.transparent_dialogue_popup:has(#loader) {
    position: fixed !important;
    inset: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    width: 100dvw !important;
    height: 100dvh !important;
    max-width: none !important;
    max-height: none !important;
    margin: 0 !important;
    padding: 0 !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    overflow: hidden !important;
}

.popup:has(#loader) :is(.popup-body, .popup-content) {
    width: 100%;
    height: 100%;
    max-height: none;
    margin: 0;
    padding: 0;
    overflow: hidden;
}

/* ---------- 居中块：一个 dl.tbox ---------- */
#loader {
    position: fixed !important;
    inset: auto !important;
    left: 50% !important;
    top: 50% !important;
    transform: translate(-50%, -50%);
    /* loader.css 的 #loader.splash-screen 有 width:100%，特异性更高，必须压过去 */
    width: min(360px, 88vw) !important;
    height: auto !important;
    max-height: none !important;
    margin: 0 !important;
    padding: 26px 22px 22px;
    display: flex !important;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    /* loader.css 里 #loader.splash-screen 有 gap: 4rem，必须压掉 */
    gap: 0 !important;
    border: 1px solid var(--mf-line);
    border-top: 3px solid var(--mf-title);
    border-radius: 0;
    background: var(--mf-paper);
    box-shadow: 2px 2px 0 rgba(197, 221, 188, 0.65);
    color: var(--mf-ink);
    font-family: var(--mf-font);
    overflow: clip;
}

/* 酒馆自带的 SillyTavern logo 不要 */
#loader .splash-logo {
    display: none !important;
}

/* 站名字标替换掉原生旋转齿轮 */
#loader #load-spinner {
    position: relative !important;
    top: auto !important;
    left: auto !important;
    order: 1;
    width: var(--mf-brand-w) !important;
    height: var(--mf-brand-h) !important;
    margin: 0 0 14px;
    font-size: 0 !important;
    color: transparent !important;
    animation: none;
    background-image: var(--mf-logo);
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
}

#loader #load-spinner::before,
#loader #load-spinner::after {
    content: none !important;
}

/* 主文案：原站那句加载提示 */
#loader::before {
    content: "正在载入,请稍候...";
    order: 2;
    color: var(--mf-title-2);
    font: 700 13px/1.5 var(--mf-font);
    letter-spacing: 2px;
}

/* 副文案：沿用酒馆原生文案，只统一字体与颜色 */
#loader .splash-message {
    order: 3;
    margin: 6px 0 0;
    color: var(--mf-ink-4);
    font: 400 11.5px/1.6 var(--mf-font) !important;
    letter-spacing: 0;
    opacity: 1;
}

/* 细进度条：1px 轨道上滑过一小段绿色 */
#loader::after {
    content: "";
    order: 4;
    width: 180px;
    height: 1px;
    margin-top: 16px;
    background-color: var(--mf-line-2);
    background-image: linear-gradient(90deg, var(--mf-title-2) 0 44px, transparent 44px);
    background-repeat: no-repeat;
    background-position: -44px 0;
    animation: mf-loading-bar 1.3s linear infinite;
}

@keyframes mf-loading-bar {
    from { background-position: -44px 0; }
    to { background-position: 180px 0; }
}

@media (prefers-reduced-motion: reduce) {
    #loader::after {
        animation: none !important;
        background-position: 0 0;
    }
}

/* 窄屏下收一圈 */
@media (max-width: 640px) {
    #loader {
        width: min(320px, 88vw) !important;
        padding: 22px 18px 18px;
    }

    #loader #load-spinner,
    #preloader::before {
        --mf-brand-h: 22px;
    }

    #loader::after {
        width: 150px;
    }
}


/*
 * 适配层：窄屏与移动端
 * 收边距、降字号、保证触摸目标；虚线列表与直角边框保持不变，不塌成现代卡片。
 */

@media (max-width: 640px) {
    :root {
        --mf-title-size: 12.5px;
        --mf-body-size: 12.5px;
        --mf-comment-size: 12.5px;
        --mf-avatar: 20px;
        --mf-avatar-comment: 22px;
        --mf-titlebar-h: 26px;
        --mf-chat-gap: 6px;
        --mf-gutter: 6px;
    }

    /* 标题条：头像更小，左侧让位同步收窄 */
    #chat .mes[is_user="false"] .ch_name {
        padding-left: 34px;
        padding-right: 4px;
    }

    #chat .mes[is_user="false"] .mesAvatarWrapper {
        top: 3px;
        left: 6px;
    }

    #chat .mes[is_user="false"] .mes_text {
        padding: 7px 9px 8px;
    }

    #chat .mes[is_user="true"] {
        padding: 5px 9px 6px;
    }

    #chat .mes[is_user="true"] .mesAvatarWrapper {
        top: 5px;
        left: 9px;
    }

    #chat .mes[is_user="true"] .ch_name {
        padding-left: 30px;
    }

    #chat .mes_reasoning_details {
        margin: 0 9px 6px;
    }

    #chat .mes[is_user="false"] .mes_block::after {
        margin: 0 9px 6px;
    }

    /* 输入区整条收窄，按钮仍保持可点 */
    #form_sheld {
        padding: 5px 6px 6px;
    }

    #nonQRFormItems {
        padding: 2px 3px;
    }

    #send_but:not(.displayNone),
    #mes_stop:not(.displayNone),
    #mes_continue:not(.displayNone),
    #mes_impersonate:not(.displayNone) {
        width: 34px;
        height: 26px;
    }

    #mes_stop {
        width: 34px !important;
        height: 26px !important;
    }

    #options_button,
    #leftSendForm .interactable {
        width: 26px;
        height: 26px;
    }

    /* 顶栏：字标缩小，给图标让位 */
    #top-settings-holder {
        padding: 0 66px 0 76px;
    }

    #top-settings-holder::before {
        left: 6px;
        width: 64px;
        height: 18px;
        background-size: auto 18px;
    }

    #rightNavHolder > .drawer-toggle {
        right: 6px;
    }

    #rightNavDrawerIcon {
        height: 20px;
        padding: 0 8px;
    }

    #rightNavDrawerIcon::after {
        font-size: 11px;
        letter-spacing: 0;
    }

    /* 欢迎页列表紧凑一档 */
    .welcomePanel .welcomeRecent .recentChatList .recentChat {
        grid-template-columns: 42px minmax(0, 1fr);
        column-gap: 8px;
        padding: 6px;
    }

    .welcomePanel .welcomeRecent .recentChatList .recentChat .avatar {
        width: 42px;
        height: 42px;
    }

    .welcomePanel .welcomeRecent .recentChatList .recentChat .chatName {
        padding-right: 0;
    }

    .welcomePanel .welcomeHeader {
        font-size: 11.5px;
    }

    .welcomePanel .welcomeShortcuts .menu_button {
        height: 20px;
        padding: 0 6px;
        font-size: 11px;
    }
}

@media (max-width: 500px) {
    /* 底部工具行在小屏只留两段，避免换行 */
    #chat .mes[is_user="false"] .mes_block::after {
        content: "分享　收藏　举报";
        font-size: 10.5px;
        letter-spacing: 0;
    }

    #chat .mes .swipes-counter {
        font-size: 10px;
    }

    /* 小屏顶栏只留字标与红按钮 */
    #top-settings-holder {
        padding: 0 60px 0 68px;
    }

    #top-settings-holder::before {
        width: 56px;
        height: 16px;
        background-size: auto 16px;
    }
}

/* 中等宽度：红按钮缩一号，右侧留白同步收窄 */
@media (min-width: 641px) and (max-width: 900px) {
    #top-settings-holder {
        padding: 0 78px 0 88px;
    }

    #rightNavHolder > .drawer-toggle {
        right: 8px;
    }

    #rightNavDrawerIcon {
        height: 20px;
        padding: 0 10px;
    }

    #rightNavDrawerIcon::after {
        font-size: 11.5px;
    }
}

/* 尊重系统「减少动态效果」 */
@media (prefers-reduced-motion: reduce) {
    #mes_stop,
    #loader::after {
        animation: none !important;
    }
}
